    /// <summary>
    /// End-to-end regression test: after the first seal commits
    /// <c>llm-tasks/completed/</c> into HEAD, the planning worktree HAS a
    /// <c>llm-tasks/</c> directory (from committed completed dir) but the
    /// pending task spec was untracked. Without
    /// <see cref="PlanningWorktree.CopyTaskSpecIntoWorktree"/> the gate flags
    /// <c>empty_task_input</c> ~250ms in because the exemption is dead. With the
    /// fix, the spec is provisioned and stage 1's input.json contains the real
    /// task markdown under <c>## Task input</c> — not blank.
    /// </summary>
    [Fact]
    public async Task RunPlanPhase_PendingTaskSpecProvisionedIntoStage1Input()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        // Folder task with distinctive markdown.
        repo.WriteNestedTask("real-spec",
            "# Real task: implement frobnicate\n\nThe frobnicator widget needs a new overload.\n",
            ("diagram.png", "fake-png-bytes"));

        // Init GitSim and commit a DONE-fake under llm-tasks/completed/ so
        // HEAD contains llm-tasks/completed/ — this is the scenario after the
        // first seal. Without the fix, the worktree's llm-tasks/ dir EXISTS
        // (from the committed completed dir) so the exemption is dead, but the
        // pending spec was never copied → empty_task_input.
        var sim = new GitSimEngine();
        sim.InitRepo(repo.Root);
        // Also commit the seed .gitkeep so the repo has a HEAD.
        sim.Seed(repo.Root, ".gitkeep", string.Empty);
        // Commit a fake completed task so llm-tasks/ enters HEAD.
        var completedDir = Path.Combine(repo.Root, "llm-tasks", "completed", "batch-001");
        Directory.CreateDirectory(completedDir);
        File.WriteAllText(Path.Combine(completedDir, "DONE-fake.md"), "# Fake completed\n");
        sim.Seed(repo.Root, "llm-tasks/completed/batch-001/DONE-fake.md", "# Fake completed\n");
        sim.Commit(repo.Root, "seed");

        // Sanity: HEAD contains llm-tasks/completed/.
        var headFiles = sim.FilesInCommit(repo.Root, sim.Head(repo.Root)!);
        Assert.Contains("llm-tasks/completed/batch-001/DONE-fake.md", headFiles);

        // The pending folder task is NOT in HEAD (untracked).
        Assert.DoesNotContain("llm-tasks/real-spec/real-spec.md", headFiles);

        var runner = new ScriptedSubagentRunner();
        runner.SeedHappyPath("src/app.cs", "tests/app.tests.cs");

        var config = PlanPhaseTestHelpers.MakeConfig(maxPlanConcurrency: 1);
        var results = await PlanPhaseRunner.RunPlanPhaseAsync(
            mainRootPath: repo.Root,
            tasks: [("real-spec", runner)],
            config: config,
            testRunner: new ScriptedTestRunner(),
            cancellationToken: CancellationToken.None,
            environmentAccessor: PlanPhaseTestHelpers.TempXdg,
            gitInvoker: sim);

        Assert.Single(results);
        // POST-FIX: the task should plan successfully, not get flagged as
        // empty_task_input.
        Assert.Equal(RelayTaskOutcomeStatus.Planned, results[0].Outcome.Status);

        // The stage-1 input artifact must contain the REAL task markdown.
        var taskDir = Path.Combine(repo.Root, ".relay", "real-spec");
        Assert.True(Directory.Exists(taskDir), ".relay/real-spec/ should exist");
        var inputJsonPath = Path.Combine(taskDir, "stage1-attempt1.input.json");
        Assert.True(File.Exists(inputJsonPath),
            "stage1-attempt1.input.json should exist in the main repo after copy-back");

        var hasInput = StageInputArtifact.TryRead(inputJsonPath, out var artifact);
        Assert.True(hasInput, "stage1-attempt1.input.json should be valid JSON");

        // The InputPrompt must contain the real spec markdown after "## Task input".
        Assert.NotNull(artifact);
        Assert.Contains("## Task input", artifact!.InputPrompt, StringComparison.Ordinal);
        Assert.Contains("frobnicate", artifact.InputPrompt, StringComparison.Ordinal);
        Assert.Contains("frobnicator widget", artifact.InputPrompt, StringComparison.Ordinal);

        // It must NOT be blank after the header.
        var taskInputSection = artifact.InputPrompt.Split("## Task input", 2, StringSplitOptions.None);
        Assert.True(taskInputSection.Length >= 2);
        Assert.False(string.IsNullOrWhiteSpace(taskInputSection[1]),
            "Task input section must not be empty/whitespace after the header");
    }

}

